TRUNCATE TABLE `services`;
INSERT INTO `services` (`id`, `title`, `slug`, `description`, `content`, `icon`, `is_featured`, `is_active`, `order`, `created_at`, `updated_at`) VALUES ('1', 'Product Management', 'product-management', 'SaaS product strategy, user story mapping, backlog prioritization (RICE/Kano), and high-velocity product execution.', '# Product Management Services

Comprehensive product leadership for SaaS startups and global tech enterprises. We run product discovery workshops, establish RICE backlog scoring models, design user-centric roadmaps, and align engineering squads to ship high-impact features fast.

### Core Capabilities:
- **Product Discovery & PMF Audits**: Identify retention leaks, analyze user cohorts, and optimize product activation metrics.
- **RICE Backlog Prioritization**: Eliminate feature bloat and align engineering deliverables with business goals.
- **User-Centric Roadmapping**: Bridge executive strategy and software sprint planning for fast release cycles.', 'target', '1', '1', '1', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `services` (`id`, `title`, `slug`, `description`, `content`, `icon`, `is_featured`, `is_active`, `order`, `created_at`, `updated_at`) VALUES ('2', 'Digital Marketing', 'digital-marketing', 'Growth digital marketing, performance funnels, and Answer Engine Optimization (AEO/GEO) for Google, ChatGPT & Perplexity.', '# Growth Digital Marketing & AEO Services

Full-funnel digital marketing strategies that turn cold traffic into sales briefings. We optimize search footprints for traditional Google SERPs and next-gen AI search surfaces (ChatGPT, Perplexity, Google AI Overviews) using QAE formatting and JSON-LD schema.

### Core Capabilities:
- **Answer Engine Optimization (AEO & GEO)**: Structure entity graphs and QAE content blocks so LLMs cite your brand as the leading authority.
- **High-Converting Performance Funnels**: Design multi-touch B2B lead acquisition pipelines and optimize Customer Acquisition Cost (CAC).
- **Search Engine Optimization (SEO)**: Code-level technical audits, site speed enhancements, and international domain strategy.', 'trending-up', '1', '1', '2', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `services` (`id`, `title`, `slug`, `description`, `content`, `icon`, `is_featured`, `is_active`, `order`, `created_at`, `updated_at`) VALUES ('3', 'Business Consulting', 'business-consulting', 'Enterprise digital transformation, decoupled web architecture advisory, and scaling offshore engineering teams from Nepal.', '# Enterprise Business Consulting Services

Strategic advisory helping global companies eliminate technical debt, modernize legacy systems using Next.js 15 + Laravel 12 REST API gateways, and scale high-performance offshore engineering squads from Nepal.

### Core Capabilities:
- **Enterprise Digital Transformation**: Migrate legacy monoliths to decoupled microservices using the Strangler Fig pattern.
- **Offshore Engineering Team Scaling**: Source, train, and manage dedicated development squads in Nepal with US/EU standards.
- **Operational & Tech Stack Audits**: Evaluate database performance, security compliance, and system release velocity.', 'briefcase', '1', '1', '3', '2026-08-13 06:27:10', '2026-08-13 06:27:10');

TRUNCATE TABLE `companies`;
INSERT INTO `companies` (`id`, `name`, `slug`, `logo`, `description`, `content`, `website_url`, `services`, `locations`, `is_active`, `order`, `created_at`, `updated_at`, `story`, `mission`, `technologies`, `industries`, `faqs`, `related_services`) VALUES ('1', 'Digital Terai', 'digital-terai', '/assets/images/companies/digitalterai.png', 'A premier Growth Digital Marketing & Search Growth Agency in Nepal, driving lead acquisition through organic search, performance funnels, and content density engines.', 'Digital Terai is a leading data-driven digital marketing agency specializing in scaling organic search engine rankings, performance advertising, and automated lead-nurturing pipelines for global and regional enterprises.', 'https://digitalterai.com', '["Growth Digital Marketing","SEO","AEO Optimization","Performance Funnels","Content Strategy"]', '["Nepal","Global"]', '1', '1', '2026-08-13 06:27:10', '2026-08-13 06:27:10', 'Digital Terai was established to engineer conversion-optimized marketing funnels that drive measurable revenue growth rather than vanity metrics.', 'To build predictable customer acquisition engines through search marketing, structured content, and automated lead nurturing.', '["Google Analytics 4","Meta Ads Manager","SEMRush","HubSpot CRM","Next.js 15"]', '["B2B SaaS","E-commerce","Real Estate","Enterprise Services"]', '[{"q":"How do you track campaign return on investment?","a":"We configure multi-touch attribution inside GA4 and tie customer conversion data back to specific campaigns, measuring CAC and LTV."},{"q":"What is Answer Engine Optimization (AEO)?","a":"AEO structures your content with QAE formatting and JSON-LD schema so AI search engines like ChatGPT and Perplexity cite your brand as an authoritative source."}]', '[{"name":"Growth Digital Marketing Services","slug":"growth-digital-marketing-and-performance-funnels"},{"name":"AEO & GEO Optimization","slug":"aeo-and-geo-optimization-chatgpt-perplexity-and-google-ai"}]');
INSERT INTO `companies` (`id`, `name`, `slug`, `logo`, `description`, `content`, `website_url`, `services`, `locations`, `is_active`, `order`, `created_at`, `updated_at`, `story`, `mission`, `technologies`, `industries`, `faqs`, `related_services`) VALUES ('2', 'IntechNexus', 'intechnexus', '/assets/images/companies/intechnexus.png', 'A global technology partner providing Remote Engineering Team as a Service, SaaS product development, AI integration, and Agile coaching.', 'IntechNexus connects high-growth technology companies in the USA, Australia, and Switzerland with dedicated, pre-vetted remote software engineering squads led by senior Product Managers and Architects.', 'https://intechnexus.com', '["Remote Engineering Teams","Product Management","Laravel 12 API Development","Next.js 15 App Router","Agile Coaching"]', '["USA","Australia","Switzerland","Nepal"]', '1', '2', '2026-08-13 06:27:10', '2026-08-13 06:27:10', 'IntechNexus addresses the global engineering talent deficit by sourcing, training, and managing top-tier software engineers skilled in modern decoupled web stacks.', 'To accelerate software product delivery for startups and enterprises through dedicated, high-velocity engineering squads.', '["Laravel 12","Next.js 15","Docker Containers","Redis","Amazon Web Services (AWS)"]', '["Enterprise SaaS Platforms","Fintech Core Systems","Digital Health"]', '[{"q":"How do you evaluate engineers?","a":"Candidates complete strict algorithmic coding tests, architectural system design challenges, and live pair-programming sessions."},{"q":"Who manages product sprint deliverables?","a":"Our dedicated squads include a certified Product Manager & Scrum Lead who aligns sprint backlogs and delivers weekly progress telemetry."}]', '[{"name":"Offshore Engineering Team Scaling","slug":"offshore-engineering-team-scaling-and-global-advisory"},{"name":"Fractional Product Management","slug":"fractional-product-management-and-saas-strategy"}]');
INSERT INTO `companies` (`id`, `name`, `slug`, `logo`, `description`, `content`, `website_url`, `services`, `locations`, `is_active`, `order`, `created_at`, `updated_at`, `story`, `mission`, `technologies`, `industries`, `faqs`, `related_services`) VALUES ('3', 'BeinSEO', 'beinseo', '/assets/images/companies/beinseo.png', 'An International SEO & AEO Consultancy based in Dubai, UAE, helping global brands rank on Google and AI search engines.', 'BeinSEO conducts code-level technical audits, executes international multi-lingual search strategies, and builds structured entity graphs for enterprise brands operating across EMEA and Global markets.', 'https://beinseo.ae', '["International SEO","AEO Optimization","Technical SEO Audits","Entity Schema Architecture"]', '["Dubai, UAE","Global"]', '1', '3', '2026-08-13 06:27:10', '2026-08-13 06:27:10', 'BeinSEO was established in Dubai to solve multi-lingual search ranking and AI citation challenges for enterprise international brands.', 'To eliminate code-level search indexation barriers and position enterprise brands as global answer authorities.', '["Cloudflare Workers","Hreflang Config","Screaming Frog","JSON-LD Schemas","Next.js 15"]', '["Logistics","E-commerce Networks","Enterprise Tech"]', '[{"q":"What is Hreflang tag configuration?","a":"It instructs search engines which regional URL to serve based on user language and location, eliminating duplicate content penalties."},{"q":"How does AEO differ from classic SEO?","a":"Classic SEO optimizes for SERP link clicks; AEO optimizes for direct answer extraction by AI models like ChatGPT and Perplexity."}]', '[{"name":"AEO & GEO Optimization","slug":"aeo-and-geo-optimization-chatgpt-perplexity-and-google-ai"}]');
INSERT INTO `companies` (`id`, `name`, `slug`, `logo`, `description`, `content`, `website_url`, `services`, `locations`, `is_active`, `order`, `created_at`, `updated_at`, `story`, `mission`, `technologies`, `industries`, `faqs`, `related_services`) VALUES ('4', 'Thoplo Machine', 'thoplo-machine', '/assets/images/companies/thoplomachine.png', 'An innovative IoT Agritech & Smart Automation venture deploying IoT sensors, remote monitoring telemetry, and automated cloud systems.', 'Thoplo Machine merges hardware engineering with cloud computing, deploying low-power LoRaWAN and NB-IoT soil sensors and microclimate trackers integrated with a central Laravel platform.', 'https://thoplomachine.com', '["IoT Systems","Agritech Automation","Cloud Telemetry","AI Ready Sensors"]', '["Nepal","South Asia"]', '1', '4', '2026-08-13 06:27:10', '2026-08-13 06:27:10', 'Thoplo Machine designs long-range IoT monitoring nodes that transmit real-time telemetry back to an autonomous cloud orchestration engine.', 'To pioneer resource-efficient automation through smart LPWAN hardware and cloud infrastructure.', '["LoRaWAN Gateway","NB-IoT Sensors","MQTT Brokers","Laravel Queues","Redis Caching"]', '["Agritech","Precision Automation","Environmental Monitoring"]', '[{"q":"What communication protocols do your sensors use?","a":"We utilize LoRaWAN for private long-range networks and NB-IoT for cellular connections."},{"q":"Is the telemetry platform real-time?","a":"Yes, telemetry packets are ingested asynchronously via MQTT brokers and updated live on Next.js dashboards."}]', '[{"name":"Enterprise Digital Transformation","slug":"enterprise-digital-transformation-and-decoupled-architecture"}]');

