INSERT INTO `testimonials` (`id`, `client_name`, `client_image`, `company_name`, `position`, `rating`, `review`, `video_url`, `is_featured`, `country`, `created_at`, `updated_at`) VALUES ('1', 'John Miller', '/assets/images/testimonials/client1.jpg', 'HealthSaaS Inc.', 'Chief Technology Officer (USA)', '5', 'Peshal served as our Fractional Product Manager and System Architect, leading the complete decoupling of our legacy monolith into Next.js 15 and Laravel 12. His sprint discipline doubled our deployment velocity while keeping our infrastructure 100% HIPAA compliant.', NULL, '1', 'USA', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
