INSERT INTO `testimonials` (`id`, `client_name`, `client_image`, `company_name`, `position`, `rating`, `review`, `video_url`, `is_featured`, `country`, `created_at`, `updated_at`) VALUES ('3', 'Markus Zbinden', '/assets/images/testimonials/client5.jpg', 'SwissTech Solutions', 'VP of Engineering (Switzerland)', '5', 'As our Business Consultant and Agile Lead, Peshal helped set up a dedicated remote development squad in Nepal. The team delivers top-tier code quality with round-the-clock agility, cutting our operational overhead by over 50%.', NULL, '1', 'Switzerland', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `testimonials` (`id`, `client_name`, `client_image`, `company_name`, `position`, `rating`, `review`, `video_url`, `is_featured`, `country`, `created_at`, `updated_at`) VALUES ('4', 'Sarah Jenkins', '/assets/images/testimonials/client4.jpg', 'EduQuest Online', 'VP of Product (Australia)', '5', 'Peshal ran a thorough SaaS Product Roadmap and PMF Audit for our learning portal. His RICE scoring framework eliminated feature bloat and improved our 30-day user retention rate by 38%. Highly recommended Product Leader.', NULL, '1', 'Australia', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `testimonials` (`id`, `client_name`, `client_image`, `company_name`, `position`, `rating`, `review`, `video_url`, `is_featured`, `country`, `created_at`, `updated_at`) VALUES ('5', 'Ram Shrestha', '/assets/images/testimonials/client3.jpg', 'GreenValley Agri-Coop', 'Managing Director (Nepal)', '5', 'Peshal’s digital transformation roadmap and Thoplo Machine IoT integration saved our agricultural greenhouses over 40% in water consumption and streamlined automated field monitoring. World-class technical leadership.', NULL, '1', 'Nepal', '2026-08-13 06:27:10', '2026-08-13 06:27:10');

TRUNCATE TABLE `portfolio_projects`;
INSERT INTO `portfolio_projects` (`id`, `title`, `slug`, `client_name`, `summary`, `content`, `main_image`, `gallery`, `technologies`, `business_outcomes`, `results_summary`, `website_url`, `is_featured`, `order`, `created_at`, `updated_at`) VALUES ('1', 'Enterprise SaaS Product Re-Architecture & Agile Roadmap Execution', 'enterprise-saas-product-re-architecture-agile-roadmap-execution', 'Global HealthSaaS Inc.', 'Product Management and System Architecture for a high-frequency clinical scheduling platform, migrating legacy PHP monolith to decoupled Next.js 15 + Laravel 12 API.', 'Peshal stepped in as Fractional Product Manager and Architect. He defined a clear Product Backlog using RICE prioritization and applied the Strangler Fig pattern to decouple UI views into Next.js 15 Server Components while exposing Laravel 12 REST endpoints.', '/assets/images/portfolio/enterprise-saas-product-re-architecture-agile-roadmap-execution.jpg', '["\/assets\/images\/portfolio\/enterprise-saas-product-re-architecture-agile-roadmap-execution-slide1.jpg","\/assets\/images\/portfolio\/enterprise-saas-product-re-architecture-agile-roadmap-execution-slide2.jpg"]', '["Product Management","Laravel 12","Next.js 15 App Router","Agile Roadmap","Redis"]', '["240% increase in sprint release velocity","3.4x faster user feature adoption","Zero downtime legacy decoupling"]', 'Delivered a decoupled portal that processes over 50,000 requests per minute with sub-50ms API response time.', 'https://healthsaas.example.com', '1', '1', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `portfolio_projects` (`id`, `title`, `slug`, `client_name`, `summary`, `content`, `main_image`, `gallery`, `technologies`, `business_outcomes`, `results_summary`, `website_url`, `is_featured`, `order`, `created_at`, `updated_at`) VALUES ('2', 'Global AEO & Generative Engine Growth Marketing Campaign', 'global-aeo-generative-engine-growth-marketing-campaign', 'B2B Tech SaaS & Dubai Logistics', 'Answer Engine Optimization (AEO) and performance marketing campaign designed to dominate AI search engine answers on ChatGPT, Perplexity, and Google AI Overviews.', 'Peshal engineered an AEO & Growth Marketing flywheel. Content was restructured using QAE answer-first blocks, entity schema markup, and high-density information gain elements.', '/assets/images/portfolio/global-aeo-generative-engine-growth-marketing-campaign.jpg', '["\/assets\/images\/portfolio\/global-aeo-generative-engine-growth-marketing-campaign-slide1.jpg","\/assets\/images\/portfolio\/global-aeo-generative-engine-growth-marketing-campaign-slide2.jpg"]', '["Growth Marketing","AEO Optimization","Next.js 15","JSON-LD Schema","Content Density"]', '["Cited in top 3 AI answers on ChatGPT & Perplexity","215% increase in organic B2B lead inquiries","100\/100 Core Web Vitals score"]', 'Positioned the client as the #1 cited authority across AI search platforms for enterprise logistics queries.', 'https://logistics.example.com', '1', '2', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `portfolio_projects` (`id`, `title`, `slug`, `client_name`, `summary`, `content`, `main_image`, `gallery`, `technologies`, `business_outcomes`, `results_summary`, `website_url`, `is_featured`, `order`, `created_at`, `updated_at`) VALUES ('3', 'Offshore Engineering Team Scaling & Digital Transformation from Nepal', 'offshore-engineering-team-scaling-digital-transformation-from-nepal', 'SwissTech Solutions & IntechNexus', 'Business consulting and staff augmentation advisory setup, establishing dedicated remote engineering squads in Nepal for European tech enterprises.', 'Peshal structured an offshore engineering scaling plan from Nepal. He vetted, hired, and onboarded senior software engineers, implementing standardized Git workflows and Scrum ceremonies.', '/assets/images/portfolio/offshore-engineering-team-scaling-digital-transformation-from-nepal.jpg', '["\/assets\/images\/portfolio\/offshore-engineering-team-scaling-digital-transformation-from-nepal-slide1.jpg","\/assets\/images\/portfolio\/offshore-engineering-team-scaling-digital-transformation-from-nepal-slide2.jpg"]', '["Business Consulting","Remote Team Management","Scrum Coaching","Digital Transformation","Nepal Squad"]', '["55% reduction in software development operating cost","99.9% uptime across production clusters","100% on-time sprint deliverables"]', 'Built a 12-person dedicated engineering squad in Kathmandu providing 24/7 technical development for Swiss enterprise software.', 'https://swisstech.example.com', '1', '3', '2026-08-13 06:27:10', '2026-08-13 06:27:10');

TRUNCATE TABLE `case_studies`;
INSERT INTO `case_studies` (`id`, `portfolio_project_id`, `title`, `slug`, `problem`, `solution`, `technology`, `approach`, `timeline_duration`, `challenges`, `results`, `roi_percentage`, `order`, `created_at`, `updated_at`) VALUES ('1', '1', 'Case Study: Enterprise SaaS Product Re-Architecture & Agile Roadmap Execution', 'case-study-enterprise-saas-product-re-architecture-agile-roadmap-execution', 'The client suffered from tight database coupling, slow releases, and feature bloat that threatened enterprise deal closures.', 'Peshal stepped in as Fractional Product Manager and Architect. He defined a clear Product Backlog using RICE prioritization and applied the Strangler Fig pattern to decouple UI views into Next.js 15 Server Components while exposing Laravel 12 REST endpoints.', '["Product Management","Laravel 12","Next.js 15 App Router","Agile Roadmap","Redis"]', 'Established 2-week agile sprint cycles with continuous integration, automated testing pipelines, and atomic Redis locks to prevent concurrent booking conflicts.', '6 Months', 'Preventing double-booking race conditions during peak hours, resolved via distributed Redis mutex locks.', 'Achieved full HIPAA compliance, accelerated feature delivery by 240%, and enabled the company to secure $1.5M in ARR.', '250', '1', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `case_studies` (`id`, `portfolio_project_id`, `title`, `slug`, `problem`, `solution`, `technology`, `approach`, `timeline_duration`, `challenges`, `results`, `roi_percentage`, `order`, `created_at`, `updated_at`) VALUES ('2', '2', 'Case Study: Global AEO & Generative Engine Growth Marketing Campaign', 'case-study-global-aeo-generative-engine-growth-marketing-campaign', 'Traditional SEO campaigns were yielding diminishing returns as buyers shifted search habits to conversational AI assistants like ChatGPT and Perplexity.', 'Peshal engineered an AEO & Growth Marketing flywheel. Content was restructured using QAE answer-first blocks, entity schema markup, and high-density information gain elements.', '["Growth Marketing","AEO Optimization","Next.js 15","JSON-LD Schema","Content Density"]', 'Audited top 10 SERP results, identified content consensus gaps, and implemented dynamic OpenGraph and JSON-LD schema layers on Next.js 15.', '4 Months', 'Tracking AI citation visibility across multiple LLM surfaces, resolved using multi-platform search telemetry tools.', 'Organic B2B lead conversions jumped 215% with zero extra ad spend, establishing long-term AI search dominance.', '310', '2', '2026-08-13 06:27:10', '2026-08-13 06:27:10');
INSERT INTO `case_studies` (`id`, `portfolio_project_id`, `title`, `slug`, `problem`, `solution`, `technology`, `approach`, `timeline_duration`, `challenges`, `results`, `roi_percentage`, `order`, `created_at`, `updated_at`) VALUES ('3', '3', 'Case Study: Offshore Engineering Team Scaling & Digital Transformation from Nepal', 'case-study-offshore-engineering-team-scaling-digital-transformation-from-nepal', 'The client faced severe local developer shortages in Zurich, inflating software R&D costs and delaying core product roadmap initiatives.', 'Peshal structured an offshore engineering scaling plan from Nepal. He vetted, hired, and onboarded senior software engineers, implementing standardized Git workflows and Scrum ceremonies.', '["Business Consulting","Remote Team Management","Scrum Coaching","Digital Transformation","Nepal Squad"]', 'Established asynchronous communication protocols, daily standups, code review checklists, and automated CI/CD pipelines.', '8 Months', 'Bridging European compliance standards with remote team workflows, resolved via strict data security policies.', 'Cut R&D costs by 55% while doubling product feature release cadence.', '210', '3', '2026-08-13 06:27:10', '2026-08-13 06:27:10');

